def transform(grid):
    height, width = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < height and 0 <= ny < width and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            components.append((color, cells))

    frames = []
    for color, cells in components:
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        border = {(r, c) for r in range(r0, r1 + 1)
                  for c in range(c0, c1 + 1)
                  if r in (r0, r1) or c in (c0, c1)}
        if set(cells) == border:
            frames.append((color, r0, r1, c0, c1, border))

    frame_cells = set().union(*(frame[5] for frame in frames)) if frames else set()
    speck_counts = Counter(grid[r][c] for r in range(height) for c in range(width)
                           if grid[r][c] != 0 and (r, c) not in frame_cells)
    frame_colors = {frame[0] for frame in frames}
    output = [[0] * width for _ in range(height)]

    for color, r0, r1, c0, c1, border in frames:
        for r, c in border:
            output[r][c] = color

    used_colors = set()
    for color, r0, r1, c0, c1, border in frames:
        top, bottom = r0 + 1, r1 - 1
        left, right = c0 + 1, c1 - 1
        required = sum(1 for r in range(top, bottom + 1)
                       for c in range(left, right + 1)
                       if (r - top + c - left) % 2 == 0)
        matches = [candidate for candidate, count in speck_counts.items()
                   if count == required and candidate not in frame_colors
                   and candidate not in used_colors]
        if matches:
            fill = matches[0]
            used_colors.add(fill)
            for r in range(top, bottom + 1):
                for c in range(left, right + 1):
                    if (r - top + c - left) % 2 == 0:
                        output[r][c] = fill
    return output
